package com.townyreborn.staffconnector;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.*;import org.bukkit.event.inventory.*;import org.bukkit.event.player.*;import org.bukkit.event.enchantment.EnchantItemEvent;import org.bukkit.plugin.Plugin;import org.bukkit.plugin.java.JavaPlugin;import org.bukkit.inventory.ItemStack;import java.util.*;import java.util.function.Consumer;
final class GameplayTelemetry implements Listener {
 private final JavaPlugin owner;private final TelemetryBuffer buffer;private final Map<String,List<String>> hooks=new HashMap<>();private final Set<String> failures=java.util.concurrent.ConcurrentHashMap.newKeySet();private final NamespacedKey origin;
 GameplayTelemetry(JavaPlugin owner,TelemetryBuffer buffer){this.owner=owner;this.buffer=buffer;origin=new NamespacedKey(owner,"spawn_origin");}
 void start(){Bukkit.getPluginManager().registerEvents(this,owner);nativeHooks();}void close(){HandlerList.unregisterAll(this);}
 void add(String plugin,String metric,String dim,Object actor,double value,Map<String,Object> details){if(actor instanceof Optional<?> o)actor=o.orElse(null);UUID id=actor instanceof OfflinePlayer p?p.getUniqueId():Reflect.uuid(actor,"getUniqueId","getUUID","getUuid");String name=actor instanceof OfflinePlayer p?p.getName():Reflect.string(actor,"","getUsername","getName");String world=actor instanceof Player p?p.getWorld().getName():"";buffer.record(plugin,metric,dim,id,name,world,value,details);}
 private void mc(String metric,String dim,Player p,double v){add("Minecraft",metric,dim,p,v,Map.of());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void blockBreak(BlockBreakEvent e){mc("blocks_broken",e.getBlock().getType().name(),e.getPlayer(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void blockPlace(BlockPlaceEvent e){mc("blocks_placed",e.getBlockPlaced().getType().name(),e.getPlayer(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void fish(PlayerFishEvent e){if(e.getState()==PlayerFishEvent.State.CAUGHT_FISH)mc("fishing_catches","all",e.getPlayer(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void spawn(CreatureSpawnEvent e){e.getEntity().getPersistentDataContainer().set(origin,org.bukkit.persistence.PersistentDataType.STRING,e.getSpawnReason().name());}
 @EventHandler(priority=EventPriority.MONITOR) public void kill(EntityDeathEvent e){Player p=e.getEntity().getKiller();if(p==null||e.getEntity() instanceof Player)return;String reason=e.getEntity().getPersistentDataContainer().get(origin,org.bukkit.persistence.PersistentDataType.STRING);add("Minecraft","mob_kills",e.getEntityType().name()+"|"+(reason==null?"UNKNOWN":reason),p,1,Map.of());}
 @EventHandler(priority=EventPriority.MONITOR) public void death(PlayerDeathEvent e){mc("player_deaths",e.getEntity().getLastDamageCause()==null?"UNKNOWN":e.getEntity().getLastDamageCause().getCause().name(),e.getEntity(),1);if(e.getEntity().getKiller()!=null)mc("player_kills","PVP",e.getEntity().getKiller(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void consume(PlayerItemConsumeEvent e){mc("items_consumed",e.getItem().getType().name(),e.getPlayer(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void craft(CraftItemEvent e){if(e.getWhoClicked() instanceof Player p&&e.getCurrentItem()!=null)mc("craft_actions",e.getCurrentItem().getType().name(),p,1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void smelt(FurnaceExtractEvent e){mc("items_smelted",e.getItemType().name(),e.getPlayer(),e.getItemAmount());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void enchant(EnchantItemEvent e){mc("items_enchanted",e.getItem().getType().name(),e.getEnchanter(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void damage(EntityDamageEvent e){if(e.getEntity() instanceof Player p)mc("damage_received",e.getCause().name(),p,e.getFinalDamage());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void teleport(PlayerTeleportEvent e){if(e.getTo()!=null)mc("teleports",e.getCause().name()+"|"+e.getTo().getWorld().getName(),e.getPlayer(),1);}
 @EventHandler(priority=EventPriority.MONITOR) public void world(PlayerChangedWorldEvent e){mc("world_changes",e.getFrom().getName()+"|"+e.getPlayer().getWorld().getName(),e.getPlayer(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void drop(PlayerDropItemEvent e){mc("items_dropped",e.getItemDrop().getItemStack().getType().name(),e.getPlayer(),e.getItemDrop().getItemStack().getAmount());}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void pickup(EntityPickupItemEvent e){if(e.getEntity() instanceof Player p)mc("items_picked_up",e.getItem().getItemStack().getType().name(),p,Math.max(0,e.getItem().getItemStack().getAmount()-e.getRemaining()));}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void breed(EntityBreedEvent e){if(e.getBreeder() instanceof Player p)mc("animals_bred",e.getEntityType().name(),p,1);}
 @EventHandler(priority=EventPriority.MONITOR) public void advancement(PlayerAdvancementDoneEvent e){if(!e.getAdvancement().getKey().getKey().startsWith("recipes/"))mc("advancements",e.getAdvancement().getKey().toString(),e.getPlayer(),1);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void command(PlayerCommandPreprocessEvent e){CommandAudit.Parsed p=CommandAudit.parse(e.getMessage());if(p==null||CommandAudit.containsSecret(p.label()))return;var cmd=Bukkit.getPluginCommand(p.label());add(cmd==null?"Minecraft":cmd.getPlugin().getName(),"commands_used",p.label(),e.getPlayer(),1,Map.of());}
 private void nativeHooks(){
  hook("Jobs","com.gamingmesh.jobs.api.JobsPaymentEvent",e->add("Jobs","money_paid","all",Reflect.call(e,"getPlayer"),Reflect.number(e,0,"getAmount"),Map.of()));
  hook("Jobs","com.gamingmesh.jobs.api.JobsExpGainEvent",e->add("Jobs","xp_gained",label(Reflect.call(e,"getJob")),Reflect.call(e,"getPlayer"),Reflect.number(e,0,"getExp"),Map.of()));
  for(String type:List.of("LevelUp","Join","Leave"))hook("Jobs","com.gamingmesh.jobs.api.Jobs"+type+"Event",e->add("Jobs",camel(type),label(Reflect.call(e,"getJob")),Reflect.call(e,"getPlayer"),1,Map.of()));
  hook("mcMMO","com.gmail.nossr50.events.experience.McMMOPlayerXpGainEvent",e->add("mcMMO","xp_gained",label(Reflect.call(e,"getSkill")),Reflect.call(e,"getPlayer"),Reflect.number(e,0,"getXpGained","getRawXpGained"),Map.of()));
  hook("mcMMO","com.gmail.nossr50.events.experience.McMMOPlayerLevelUpEvent",e->add("mcMMO","level_ups",label(Reflect.call(e,"getSkill")),Reflect.call(e,"getPlayer"),Reflect.number(e,1,"getLevelsGained"),Map.of()));
  hook("PyroFishingPro","me.arsmagica.API.PyroFishCatchEvent",e->add("PyroFishingPro","fish_caught",Reflect.string(e,"unknown","getTier")+" #"+(int)Reflect.number(e,0,"getFishNumber"),Reflect.call(e,"getPlayer"),1,Map.of("hotspot",Reflect.bool(e,false,"isHotspot"))));
  for(String type:List.of("Start","End"))hook("PyroFishingPro","me.arsmagica.API.Tournament"+type+"Event",e->add("PyroFishingPro","tournament_"+type.toLowerCase(Locale.ROOT),"",null,1,Map.of()));
  for(String type:List.of("Start","Finish","Cancel","Expire"))hook("Quests","com.leonardobishop.quests.bukkit.api.event.Player"+type+"QuestEvent",e->add("Quests","quests_"+type.toLowerCase(Locale.ROOT),Reflect.string(Reflect.call(e,"getQuestProgress"),"unknown","getQuestId"),Reflect.call(e,"getPlayer"),1,Map.of()));
  for(String type:List.of("Open","ObtainReward"))hook("ExcellentCrates","su.nightexpress.excellentcrates.api.event.Crate"+type+"Event",e->add("ExcellentCrates",type.equals("Open")?"crate_open_actions":"rewards_obtained",label(Reflect.call(e,"getCrate")),Reflect.call(e,"getPlayer"),1,Map.of()));
  hook("AxAuctions","com.artillexstudios.axauctions.api.events.AxAuctionsSellEvent",e->add("AxAuctions","listings_created",item(Reflect.call(e,"getItem")),Reflect.call(e,"getPlayer"),1,Map.of()));
  hook("AxAuctions","com.artillexstudios.axauctions.api.events.AxAuctionsPurchaseEvent",e->{Object a=Reflect.call(e,"getItem"),p=Reflect.call(e,"getPlayer");add("AxAuctions","sales_completed",item(a),p,1,Map.of());add("AxAuctions","sales_value",item(a),p,Reflect.number(a,0,"getPrice"),Map.of("currency",label(Reflect.call(a,"getCurrency"))));});
  hook("QuickShop-Hikari","com.ghostchu.quickshop.api.event.economy.ShopSuccessPurchaseEvent",e->{Object p=Reflect.call(e,"getPurchaser"),shop=Reflect.call(e,"getShop");add("QuickShop-Hikari","shop_transactions",item(shop),p,1,Map.of());add("QuickShop-Hikari","items_traded",item(shop),p,Reflect.number(e,0,"getAmount"),Map.of());add("QuickShop-Hikari","trade_value",item(shop),p,Reflect.number(e,0,"getBalanceWithoutTax"),Map.of());});
  for(String type:List.of("Create","Delete"))hook("QuickShop-Hikari","com.ghostchu.quickshop.api.event.management.Shop"+type+"Event",e->add("QuickShop-Hikari","shops_"+type.toLowerCase(Locale.ROOT),item(Reflect.call(e,"shop")),Reflect.call(e,"user"),1,Map.of()));
  for(String type:List.of("NewTown","DeleteTown","NewNation","DeleteNation","TownClaim","TownUnclaim","TownAddResident","TownRemoveResident"))hook("Towny","com.palmergames.bukkit.towny.event."+type+"Event",e->add("Towny",camel(type),label(Reflect.call(e,"getTown","getNation")),Reflect.call(e,"getPlayer","getResident","getMayor"),1,Map.of()));
  hook("Votifier","com.vexsoftware.votifier.model.VotifierEvent",e->{Object v=Reflect.call(e,"getVote");String name=Reflect.string(v,"","getUsername");add("Votifier","votes",Reflect.string(v,"unknown","getServiceName"),new Named(name),1,Map.of());});
  for(String type:List.of("RightClick","LeftClick"))hook("Citizens","net.citizensnpcs.api.event.NPC"+type+"Event",e->add("Citizens","npc_interactions",label(Reflect.call(e,"getNPC")),Reflect.call(e,"getClicker"),1,Map.of()));
  hook("Essentials","net.ess3.api.events.AfkStatusChangeEvent",e->add("Essentials","afk_changes",Reflect.bool(e,false,"getValue")?"AFK":"ACTIVE",Reflect.call(Reflect.call(e,"getAffected"),"getBase"),1,Map.of()));
  for(String type:List.of("EntitySit","PlayerCrawl","PlayerLay"))hook("GSit","dev.geco.gsit.api.event."+type+"Event",e->add("GSit","poses_started",type,Reflect.call(e,"getPlayer","getEntity"),1,Map.of()));
  for(String type:List.of("PinataSpawn","PinataDie"))hook("PinataParty","me.hexedhero.pp.api."+type+"Event",e->add("PinataParty",camel(type),"",null,1,Map.of()));
  hook("ArtMap","me.Fupery.ArtMap.Event.PlayerMountEaselEvent",e->add("ArtMap","painting_sessions","",Reflect.call(e,"getPlayer"),1,Map.of()));
  hook("MythicMobs","io.lumine.mythic.bukkit.events.MythicMobDeathEvent",e->add("MythicMobs","mythic_mob_deaths",label(Reflect.call(e,"getMobType")),Reflect.call(e,"getKiller"),1,Map.of()));
 }
 @SuppressWarnings("unchecked") private void hook(String plugin,String className,Consumer<Object> action){Plugin p=Bukkit.getPluginManager().getPlugin(plugin);if(p==null||!p.isEnabled())return;try{Class<?> c=Class.forName(className,false,p.getClass().getClassLoader());if(!Event.class.isAssignableFrom(c))return;Bukkit.getPluginManager().registerEvent((Class<? extends Event>)c,this,EventPriority.MONITOR,(l,e)->{if(!c.isInstance(e)||e instanceof Cancellable cancelled&&cancelled.isCancelled())return;Object phase=Reflect.call(e,"phase");if(phase instanceof Enum<?> step&&!step.name().equals("POST"))return;try{action.accept(e);}catch(LinkageError|RuntimeException problem){if(failures.add(className))owner.getLogger().warning("Telemetry hook unavailable: "+className+" "+problem.getClass().getSimpleName());}},owner,true);hooks.computeIfAbsent(plugin,k->new ArrayList<>()).add(className);}catch(LinkageError|ReflectiveOperationException|RuntimeException failure){failures.add(className);}}
 Map<String,Object> coverage(Plugin p){List<String> list=hooks.getOrDefault(p.getName(),List.of());return Map.of("coverage",list.isEmpty()?"technical":"native","hooks",list.size(),"hook_names",list,"hook_failures",failures.size(),"category",category(p.getName()));}
 private static String camel(String s){return s.replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase(Locale.ROOT);}private static String label(Object o){if(o instanceof Optional<?> opt)o=opt.orElse(null);if(o instanceof String s)return s;if(o instanceof Enum<?> e)return e.name();return Reflect.string(o,"unknown","getId","getID","getName","getInternalName");}private static String item(Object o){if(o instanceof Optional<?> v)o=v.orElse(null);if(o instanceof ItemStack i)return i.getType().name();Object stack=Reflect.call(o,"getItemStack","getItem");return stack instanceof ItemStack i?i.getType().name():label(o);}private record Named(String name){public String getUsername(){return name;}}
 static String category(String name){String n=name.toLowerCase(Locale.ROOT);if(n.matches(".*(jobs|auction|shop|vault|tebex|subscription).*"))return "Economy";if(n.matches(".*(fish|quest|mcmmo|progression|parkour|catchball|artmap|pinata|chatgames).*"))return "Gameplay";if(n.matches(".*(towny|world|chunk|portal|rtp).*"))return "World & Towny";if(n.matches(".*(ban|vulcan|protect|vanish|staff|lpx|permission|openinv).*"))return "Moderation";if(n.matches(".*(model|item|cosmetic|glow|crates|citizen|hologram|nametag|namecolor|tab).*"))return "Visuals";return "Infrastructure";}
}
